use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Registry { # [doc = " Creates a registry which can hold up to `thread_limit` threads."] pub fn new (thread_limit : NonZero < usize >) -> Self { Registry (Arc :: new (RegistryData { thread_limit , threads : Mutex :: new (0) })) } # [doc = " Gets the registry associated with the current thread. Panics if there's no such registry."] pub fn current () -> Self { REGISTRY . with (| registry | registry . get () . cloned () . expect ("No associated registry")) } # [doc = " Registers the current thread with the registry so worker locals can be used on it."] # [doc = " Panics if the thread limit is hit or if the thread already has an associated registry."] pub fn register (& self) { let mut threads = self . 0 . threads . lock () ; if * threads < self . 0 . thread_limit . get () { REGISTRY . with (| registry | { if registry . get () . is_some () { drop (threads) ; panic ! ("Thread already has a registry") ; } registry . set (self . clone ()) . ok () ; THREAD_DATA . with (| data | { data . registry_id . set (self . id ()) ; data . index . set (* threads) ; }) ; * threads += 1 ; }) ; } else { drop (threads) ; panic ! ("Thread limit reached") ; } } # [doc = " Gets the identifier of this registry."] fn id (& self) -> RegistryId { RegistryId (& * self . 0) } }